/**
 * Email provider config types — Sawaa Dashboard
 *
 * Every RESPONSE shape is derived from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`), so a
 * backend response change becomes a type error here instead of drifting
 * silently. `test/unit/lib/comms-type-contract.spec.ts` pins that.
 *
 * Credentials are write-only: the GET/POST view carries only the boolean
 * `credentialsConfigured`, never a key, password, token or ciphertext. The
 * hand-written `organizationId` field is gone — no handler has ever sent it
 * (the settings row is a single-tenant singleton), and nothing in the
 * dashboard reads it.
 */

import type { components } from "@/lib/types/api.generated"

type Schemas = components["schemas"]

/* ─── Entities (derived from OpenAPI) ─── */

/** `provider` as the wire spells it (`OrganizationEmailConfig.provider`). */
export type EmailProviderName = Schemas["EmailSettingsResponseDto"]["provider"]

/** The whole email settings view; the settings form is the only reader. */
export type EmailConfigView = Schemas["EmailSettingsResponseDto"]

/** One SMTP block inside the upsert body. */
export type SmtpCredentialsInput = NonNullable<Schemas["UpsertOrgEmailConfigDto"]["smtp"]>

/** `POST /dashboard/comms/settings/email` body. */
export type UpsertEmailConfigInput = Schemas["UpsertOrgEmailConfigDto"]

/** `POST /dashboard/comms/settings/email/test` result. */
export type TestEmailResult = Schemas["EmailSettingsTestResultDto"]
